const [errors, setErrors] = useState({});
const [reveal, setReveal] = useState(0);

<form noValidate onSubmit={(e) => { e.preventDefault(); const next = validate(form); setErrors(next); setReveal((r) => r + 1); if (!Object.keys(next).length) save(); }}>
  <ErrorSummary
    errors={Object.entries(errors).map(([key, message]) => ({ field: "f-" + key, message }))}
    title={(n) => (n === 1 ? "1 thing to fix" : `${n} things to fix`)}
    revealErrors={reveal}
    scrollMargin={72}
  />
  <TextField id="f-email" label="Email" labelPlacement="above" error={errors.email} revealErrors={reveal} />
</form>

function Stars() {
  const f = useField();
  return <div role="slider" tabIndex={f.disabled ? -1 : 0} aria-valuemin={0} aria-valuemax={5} aria-valuenow={rating} {...f} />;
}

<Field label="How was it?" hint="Five is best."><Stars /></Field>
